use std::collections::HashSet;

fn exec_last_occurrence_position(cafes: &Vec<i8>, cafe: i8) -> usize {
    // Find the last index where `cafe` appears.
    // rposition returns an Option<usize>, unwrap is safe because we know `cafe` is in the array.
    cafes.iter().rposition(|&x| x == cafe).unwrap()
}

fn solve(cafes: Vec<i8>) -> i8 {
    // Initialize with the first element's last occurrence.
    let mut best_cafe = cafes[0];
    let mut best_pos = exec_last_occurrence_position(&cafes, best_cafe);

    // Keep track of which cafes we've already checked.
    let mut seen = HashSet::new();
    for &cafe in &cafes {
        if seen.insert(cafe) {
            let pos = exec_last_occurrence_position(&cafes, cafe);
            if pos < best_pos {
                best_pos = pos;
                best_cafe = cafe;
            }
        }
    }

    best_cafe
}

